def svg_ic(nome, w=30, m="#3F4ACB", a="#B6EC0C", wcor="#FFFFFF"):
    """v3: delega para icons3 (grade, peso e cantos normalizados)."""
    from icons3 import ic3
    return ic3(nome, w, m=m, a=a, wcor=wcor)
